set -euo pipefail
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';
const root='/var/lib/news-flow/category-coverage-20261123',db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:20000}),rows=db.prepare("SELECT * FROM (SELECT c.site,c.url original_url,r.url,r.es_index,r.es_type,r.es_id,r.status,r.imported_at,row_number() OVER(PARTITION BY c.site ORDER BY (r.status='created') DESC,r.imported_at DESC) n FROM news_category_backfill c JOIN import_receipts r ON r.id=c.es_id AND r.es_index=c.es_index) WHERE n=1 ORDER BY site").all(),r={at:new Date().toISOString(),rows:[]};
try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('ES_IDENTITY_CHANGED');const result=rows.length?await es.mget({body:{docs:rows.map(a=>({_index:a.es_index,_type:a.es_type,_id:a.es_id}))}}):{docs:[]};for(let i=0;i<rows.length;i++){const row=rows[i],hit=result.docs[i],s=hit?._source;r.rows.push({site:row.site,url:row.original_url,storedUrl:row.url,receiptStatus:row.status,index:row.es_index,id:row.es_id,found:hit?.found===true,urlMatches:s?.url===row.url,titlePresent:typeof s?.title==='string'&&s.title.trim().length>0,contentPresent:typeof s?.content==='string'&&s.content.length>0,publishedDate:s?.publishedDate,publicationValid:typeof s?.publishedDate==='string'&&Number.isFinite(Date.parse(s.publishedDate)),bodyLength:s?.content?.length});}r.checked=r.rows.length;r.verified=r.checked>0&&r.rows.every(a=>a.found&&a.urlMatches&&a.titlePresent&&a.contentPresent&&a.publicationValid);fs.writeFileSync(root+'/es-readback.json',JSON.stringify(r,null,2));console.log(JSON.stringify({at:r.at,checked:r.checked,verified:r.verified,vnexpress:r.rows.find(a=>a.site==='vnexpress.net'),failed:r.rows.filter(a=>!a.found||!a.urlMatches||!a.titlePresent||!a.contentPresent||!a.publicationValid)}));}catch(error){console.log(JSON.stringify({verified:false,error:/^[A-Z0-9_]+$/.test(error.message||'')?error.message:'ES_READBACK_FAILED'}));process.exitCode=1;}finally{db.close();es.close();}
NODE
